                        {connectedEndpoint ? 'Connected' : 'Connect'}
                    </Button>
                </span>
            </Tooltip>
            <RemoteConnectDialog
                connectedEndpoint={connectedEndpoint}
                errorMessage={errorMessage}
                isBusy={isBusy}
                onClose={() => setIsDialogOpen(false)}
                onConnect={(settings) => void handleConnect(settings)}
                onDisconnect={handleDisconnect}
                open={isDialogOpen}
            />
        </>
    )
}

